import { expect, test, uniqueName } from "../../fixtures";

const DOCUMENTS = {
  w9: "Legal Name: Review Co LLC\nTax ID: 84-2219067\nBusiness Type: LLC\n",
  insurance_certificate: "Insurer: Harbor Mutual\nPolicy Number: HM-55-1290\nCoverage Amount: $2,000,000\nExpiry Date: 2099-03-31\n",
  contract: "Counterparty: Review Co LLC\nEffective Date: 2026-01-01\nExpiry Date: 2099-12-31\n",
} as const;

test("approving every extraction approves the vendor", { tag: "@REV-05" }, async ({ apiAs }) => {
  // Arrange: a vendor in review with three extracted documents
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");

  const created = await member.post("/api/vendors", {
    data: { name: uniqueName("Review Co"), category: "logistics", contact_email: "ops@reviewco.example" },
  });
  expect(created.status(), await created.text()).toBe(201);
  const vendor = (await created.json()) as { id: string };

  for (const [kind, text] of Object.entries(DOCUMENTS)) {
    const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind,
        file: { name: `${kind}.txt`, mimeType: "text/plain", buffer: Buffer.from(text) },
      },
    });
    expect(upload.status(), await upload.text()).toBe(201);
  }

  // Extraction runs in the background; wait until all three documents are extracted.
  await expect
    .poll(
      async () => {
        const res = await member.get(`/api/vendors/${vendor.id}/documents`);
        const docs = (await res.json()) as { status: string }[];
        return docs.length === 3 && docs.every((d) => d.status === "extracted");
      },
      { timeout: 60_000 },
    )
    .toBe(true);

  const submitted = await member.post(`/api/vendors/${vendor.id}/submit`);
  expect(submitted.status(), await submitted.text()).toBe(200);
  expect((await submitted.json()).status).toBe("in_review");

  const docs = (await (await member.get(`/api/vendors/${vendor.id}/documents`)).json()) as {
    id: string;
  }[];
  const extractions: { id: string; status: string }[] = [];
  for (const doc of docs) {
    const res = await member.get(`/api/documents/${doc.id}/extraction`);
    expect(res.status(), await res.text()).toBe(200);
    extractions.push(await res.json());
  }
  expect(extractions).toHaveLength(3);
  expect(extractions.every((e) => e.status === "pending_review")).toBe(true);

  // Act: reviewer approves all three extractions
  for (const extraction of extractions) {
    const decision = await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
      data: { decision: "approve" },
    });
    expect(decision.status(), await decision.text()).toBe(200);
  }

  // Assert: vendor becomes approved and the audit trail records it
  await expect
    .poll(
      async () => {
        const res = await member.get(`/api/vendors/${vendor.id}`);
        return ((await res.json()) as { status: string }).status;
      },
      { timeout: 30_000 },
    )
    .toBe("approved");

  const trail = await member.get(`/api/vendors/${vendor.id}/audit`);
  expect(trail.status(), await trail.text()).toBe(200);
  const actions = ((await trail.json()) as { items: { action: string }[] }).items.map((e) => e.action);
  expect(actions, JSON.stringify(actions)).toContain("vendor.approved");
});
